def rpn_eval(expression: str) -> float:
    """
    Evaluates a Reverse Polish Notation (postfix) arithmetic expression.

    Args:
        expression: A space-separated string of operands and operators

    Returns:
        The result of the RPN expression as a float

    Raises:
        ValueError: If the expression is invalid (empty, malformed, or has 
                   insufficient operands for operators)
    """
    if not expression.strip():
        raise ValueError("Empty expression")

    tokens = expression.split()
    stack = []

    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"Not enough operands for operator '{token}'")

            # Pop two operands (order matters for subtraction and division)
            operand2 = stack.pop()
            operand1 = stack.pop()

            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                if operand2 == 0:
                    raise ValueError("Division by zero")
                result = operand1 / operand2

            stack.append(result)
        else:
            try:
                # Try to parse as float
                value = float(token)
                stack.append(value)
            except ValueError:
                raise ValueError(f"Unknown token: '{token}'")

    if len(stack) != 1:
        raise ValueError("Invalid expression: leftover operands")

    return stack[0]

